import{_ as t,o as e,c as i,a2 as r}from"./chunks/framework.C-si7TFR.js";const _=JSON.parse('{"title":"项目、角色与凭证","description":"","frontmatter":{"title":"项目、角色与凭证"},"headers":[],"relativePath":"zh/guide/administration.md","filePath":"zh/guide/administration.md"}'),o={name:"zh/guide/administration.md"};function l(n,a,s,d,h,c){return e(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="项目、角色与凭证" tabindex="-1">项目、角色与凭证 <a class="header-anchor" href="#项目、角色与凭证" aria-label="Permalink to &quot;项目、角色与凭证&quot;">​</a></h1><h2 id="项目空间" tabindex="-1">项目空间 <a class="header-anchor" href="#项目空间" aria-label="Permalink to &quot;项目空间&quot;">​</a></h2><p>项目用于组织 Agent、工作流、资源与成员。执行创建、编辑或导出前先确认当前项目，不要仅凭资源名称判断归属。</p><p>从用户管理或相关项目入口创建项目、添加成员并分配角色。项目可见性、成员来源和入口可能随角色与部署变化。</p><h2 id="角色不是全部权限" tabindex="-1">角色不是全部权限 <a class="header-anchor" href="#角色不是全部权限" aria-label="Permalink to &quot;角色不是全部权限&quot;">​</a></h2><ul><li><strong>管理员</strong>、<strong>编辑者</strong>、<strong>浏览者</strong>等角色影响可见菜单与操作范围。</li><li>能查看资源不等于能修改、执行、导出或访问其全部底层数据。</li><li>角色入口不能被解释为行级、字段级权限，也不能替代工具目录和远程白名单限制。</li></ul><p>创建共享资源前确认哪些角色可见。导出和分享时同时检查配置中的凭证、地址、提示词和业务数据。</p><h2 id="凭证与模型" tabindex="-1">凭证与模型 <a class="header-anchor" href="#凭证与模型" aria-label="Permalink to &quot;凭证与模型&quot;">​</a></h2><ol><li>在受控的凭证管理入口创建对应服务类型的凭证。</li><li>在服务商后台生成独立的秘密，只授予所需权限。</li><li>将秘密填入本地凭证配置，不写入公开 Markdown、截图或示例仓库。</li><li>在目标节点或配置中选择凭证，并用无副作用请求测试。</li><li>离职、泄露或用途变化时撤销／轮换秘密，并检查相关引用。</li></ol><p>模型配置可在 Agent 对话的模型设置入口完成。凭证与模型可用性受服务商、网络、项目配置和部署条件影响。</p><h2 id="工具和数据边界" tabindex="-1">工具和数据边界 <a class="header-anchor" href="#工具和数据边界" aria-label="Permalink to &quot;工具和数据边界&quot;">​</a></h2><p>文件、SSH、脚本、HTTP 与 MCP 会触达实际系统。采用最小授权、固定目录和目标白名单，使用参数绑定，禁止将用户输入直接拼接到命令或 SQL。远程通道必须配置用户白名单，不能用隐藏链接代替身份验证。</p>',12)])])}const u=t(o,[["render",l]]);export{_ as __pageData,u as default};
